const $=id=>document.getElementById(id),D=Darts,KEY='oche-perfect-v1';
let data;try{data=JSON.parse(localStorage.getItem(KEY));}catch{}if(!data||!Array.isArray(data.history)||!data.session)data={history:[],session:newSession('exam'),hints:false};
let mult='S',undoStack=[],typed='',entryMode=data.session.game.dart&&data.session.game.status==='playing'?'dart':(data.entryMode||'total'),feedback='';
const dartsUsed=g=>g.throws.reduce((n,t)=>n+(t.darts||1),0);
function newSession(mode){return {id:globalThis.crypto?.randomUUID?.()||String(Date.now()),date:new Date().toISOString(),mode,legs:[],game:D.fresh(),assisted:false};}
function allLegs(s){return [...s.legs,...(s.game.throws.length||s.game.status!=='playing'?[s.game]:[])];}
function terminal(s){return s.game.status==='won'||(s.game.status==='lost'&&(s.mode==='solo'||s.legs.length===4));}
function save(){const s=data.session;data.history=data.history.filter(h=>h.id!==s.id);if(terminal(s))data.history.unshift({...structuredClone(s),complete:true});try{localStorage.setItem(KEY,JSON.stringify(data));}catch{feedback='Browser storage is unavailable. Export your history before closing.';}}
function stat(g){const ts=g.throws.filter(t=>!t.aggregate),ch=ts.filter(t=>t.checkoutChance),bull=ts.filter(t=>t.label==='25'||t.label==='BULL'),used=dartsUsed(g);return {avg:used?((501-g.remaining)/used*3).toFixed(1):'—',bust:g.visits.filter(v=>v.bust).length,checkout:ch.length?ch.filter(t=>!t.bust&&t.before===t.value&&D.get(t.label).double).length+'/'+ch.length:'—',bull:ts.length?Math.round(bull.length/ts.length*100)+'%':'—'};}
function record(label){const s=data.session;if(s.game.status!=='playing')return;undoStack.push(structuredClone(s));if(data.hints)s.assisted=true;const before=s.game; s.game=D.throwDart(before,label,$('aim').value||null,data.hints);const last=s.game.throws.at(-1);feedback=last.bust?'Bust. This round’s points are removed.':s.game.status==='won'?'Double out. You’ve got your finish.':s.game.status==='lost'?'Eight rounds complete. Review this attempt below.':`${label} · ${s.game.remaining} remaining${s.game.round>before.round?' · Next round':''}.`;mult='S';save();render();}
function render(){const s=data.session,g=s.game,st=stat(g),done=g.status!=='playing';$('examMode').classList.toggle('selected',s.mode==='exam');$('soloMode').classList.toggle('selected',s.mode==='solo');$('hints').checked=!!data.hints;$('attemptTitle').textContent=s.mode==='exam'?`ATTEMPT ${String(s.legs.length+1).padStart(2,'0')} / 05`:'SINGLE LEG PRACTICE';$('attempts').innerHTML=s.mode==='exam'?Array.from({length:5},(_,i)=>`<span class="attempt-dot ${i<s.legs.length?s.legs[i].status:i===s.legs.length?done?g.status:'current':''}">${i<s.legs.length?'×':i===s.legs.length&&g.status==='won'?'✓':i+1}</span>`).join(''):'';
 $('score').textContent=g.remaining;$('scoreLabel').textContent=g.status==='won'?'CHECKOUT COMPLETE':g.status==='lost'?'ATTEMPT COMPLETE':'POINTS REMAINING';$('round').textContent=g.round;const consumed=(g.round-1)*3+g.dart;$('dartCount').textContent=done?`${dartsUsed(g)} darts thrown`:`${24-consumed} darts left`;$('roundTrack').innerHTML=Array.from({length:8},(_,i)=>`<i class="${i+1<g.round?'done':i+1===g.round?'current':''}"></i>`).join('');const current=g.throws.filter(t=>t.round===g.round);$('dartSlots').innerHTML=Array.from({length:3},(_,i)=>`<div class="dart-slot ${!done&&i===g.dart?'active':''}"><small>DART ${i+1}</small><b>${current[i]?.label||'—'}</b></div>`).join('');document.querySelectorAll('[data-hit], [data-number], [data-mult]').forEach(b=>b.disabled=done);document.querySelectorAll('[data-mult]').forEach(b=>b.classList.toggle('selected',b.dataset.mult===mult));$('undo').disabled=!undoStack.length;$('average').textContent=st.avg;$('busts').textContent=st.bust;$('doubleRate').textContent=st.checkout;$('bullRate').textContent=st.bull;$('feedback').textContent=feedback;
 const rows=[...g.visits];if(g.dart>0&&!done&&!g.visits.some(v=>v.round===g.round))rows.push({round:g.round,labels:current.map(t=>t.label),score:g.visitStart-g.remaining,end:g.remaining,pending:true});$('visitList').innerHTML=rows.length?rows.map(v=>`<div class="visit-row"><small>R${v.round}</small><span>${v.labels.join(' · ')}${v.bust?' <small>BUST</small>':''}${v.pending?' <small>LIVE</small>':''}</span><strong>${v.score}</strong><em>${v.end}</em></div>`).join(''):'<p class="muted">Your first round starts here.</p>';
 $('assistState').textContent=data.hints?'ON':'OFF';
 if(!data.hints)$('hintContent').innerHTML='Exam conditions · no hints';else if(done)$('hintContent').innerHTML='Leg complete';else{const h=D.arrange(g.remaining,3-g.dart);$('hintContent').innerHTML=`<div class="hint-route">${h.labels.map(x=>`<b>${x}</b>`).join('<span>→</span>')}<span class="hint-note">${h.type==='checkout'?'finish':`leave ${h.leave||'—'}`}</span></div>`;}
 $('totalInput').hidden=entryMode!=='total';$('dartInput').hidden=entryMode!=='dart';$('totalMode').classList.toggle('selected',entryMode==='total');$('dartMode').classList.toggle('selected',entryMode==='dart');$('typedScore').textContent=typed||'0';$('submitScore').disabled=done||typed==='';$('bustButton').disabled=done;$('endActions').hidden=!done;document.querySelector('.entry').hidden=done;$('feedback').textContent=feedback||(entryMode==='total'?'Enter your three-dart total.':'Tap the segment you hit. Double / Triple resets after each dart.');
 $('endActions').innerHTML=done?`<h2>${g.status==='won'?(s.mode==='exam'?'Mock exam passed.':'Leg complete.'):(terminal(s)?(s.mode==='exam'?'Five chances. Keep building.':'Keep building.'):'Reset. Go again.')}</h2><p>${g.status==='won'?`501 finished in ${dartsUsed(g)} darts. ${s.assisted?'Assisted session.':'Hints stayed off.'}`:terminal(s)?(s.mode==='exam'?'No finish this time. Your full session is in Progress.':'Your leg is saved in Progress.'):`${5-s.legs.length-1} attempts left. You only need one finish.`}</p><button class="primary" id="next">${terminal(s)?'Start a new session':'Next attempt →'}</button>`:'';
 if(done)$('next').onclick=()=>{if(terminal(data.session)){data.session=newSession(s.mode);undoStack=[];}else{data.session.legs.push(data.session.game);data.session.game=D.fresh();}typed='';feedback='';save();render();};$('historyCount').textContent=data.history.length;renderHistory();}
function renderHistory(){const hs=data.history,complete=hs.filter(s=>s.complete),exams=complete.filter(s=>s.mode==='exam'),unassisted=exams.filter(s=>!s.assisted),passed=ss=>ss.filter(s=>allLegs(s).some(g=>g.status==='won')).length,legs=hs.flatMap(allLegs),throws=legs.flatMap(g=>g.throws).filter(t=>!t.aggregate),bust=legs.reduce((n,g)=>n+stat(g).bust,0);$('progressStats').innerHTML=[[exams.length,'Completed mock exams'],[exams.length?Math.round(passed(exams)/exams.length*100)+'%':'—','Mock exam pass rate'],[unassisted.length?Math.round(passed(unassisted)/unassisted.length*100)+'%':'—','Unassisted pass rate'],[legs.length,'Recorded legs']].map(([v,l])=>`<div class="progress-stat"><b>${v}</b><span>${l}</span></div>`).join('');
 const aimed=throws.filter(t=>t.aim),doubleAims=aimed.filter(t=>D.get(t.aim)?.double),doubleHits=doubleAims.filter(t=>t.label===t.aim),slow=legs.filter(g=>g.status==='lost'&&g.remaining>170).length,finish=legs.filter(g=>g.status==='lost'&&g.remaining<=170).length;
 $('insights').innerHTML=legs.length?`<b>What the log says</b><br>${bust} bust visit${bust===1?'':'s'} across ${legs.length} legs. ${slow} failed legs ended above 170; ${finish} ended at 170 or below.<br>${doubleAims.length?`Intended doubles: ${doubleHits.length}/${doubleAims.length} hit (${Math.round(doubleHits.length/doubleAims.length*100)}%).`:'Track your intended target during practice to measure double accuracy.'}<br><span class="fine">These are observations, not a diagnosis. Checkout hits count darts thrown while a one-dart finish was available. Bull hits count both 25 and 50.</span>`:'Your patterns will appear after your first completed leg. You can also save a partial session by starting fresh.';
 $('historyList').innerHTML=hs.length?hs.map(s=>{const ls=allLegs(s),won=ls.some(g=>g.status==='won');return `<details class="history-entry"><summary><span>${new Date(s.date).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${s.mode==='exam'?'Mock exam':'Single leg'}</span><span class="badge ${won?'pass':''}">${s.complete?(won?'PASS':'NO FINISH'):'INCOMPLETE'} · ${s.assisted?'ASSISTED':'UNASSISTED'}</span></summary>${ls.map((g,i)=>`<p><b>Attempt ${i+1}</b> · ${g.status==='won'?'Finished':`${g.remaining} left`} · ${dartsUsed(g)} darts · ${stat(g).avg} average · ${stat(g).bust} busts<br>${g.visits.map(v=>`R${v.round}: ${v.labels.join(' / ')} → ${v.bust?'Bust':v.score} (${v.end} left)`).join('<br>')}</p>`).join('')}</details>`;}).join(''):'<p class="muted">A clean slate. Your finished sessions will show up here.</p>';
}
function start(mode){$('settingsDialog').close();const s=data.session;if(allLegs(s).length&&!terminal(s)){pendingMode=mode;$('confirmDialog').showModal();return;}data.session=newSession(mode);undoStack=[];typed='';feedback='';save();render();}
let pendingMode='exam';$('restart').onclick=()=>start(data.session.mode);$('examMode').onclick=()=>{if(data.session.mode!=='exam')start('exam');};$('soloMode').onclick=()=>{if(data.session.mode!=='solo')start('solo');};$('cancelRestart').onclick=()=>$('confirmDialog').close();$('confirmRestart').onclick=()=>{const s=data.session;if(allLegs(s).length&&!terminal(s))data.history.unshift({...structuredClone(s),complete:false});data.session=newSession(pendingMode);undoStack=[];typed='';feedback='';$('confirmDialog').close();save();render();};
 $('numbers').innerHTML=Array.from({length:20},(_,i)=>`<button data-number="${20-i}">${20-i}</button>`).join('');document.querySelectorAll('[data-number]').forEach(b=>b.onclick=()=>record(mult+b.dataset.number));document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>record(b.dataset.hit));document.querySelectorAll('[data-mult]').forEach(b=>b.onclick=()=>{mult=b.dataset.mult;render();});
 $('aim').innerHTML+=D.targets.filter(t=>t.value).map(t=>`<option value="${t.label}">${t.label==='BULL'?'Inner bull (50)':t.label==='25'?'Outer bull (25)':t.label}</option>`).join('');$('hints').onchange=()=>{data.hints=$('hints').checked;if(data.hints)data.session.assisted=true;save();render();};$('undo').onclick=()=>{if(undoStack.length){const assisted=data.session.assisted;data.session=undoStack.pop();typed='';if(data.session.game.dart&&data.session.game.status==='playing')entryMode='dart';data.session.assisted ||= assisted;feedback='Last dart undone.';save();render();}};
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));for(const id of ['practice','rounds','history'])$(id).hidden=b.dataset.tab!==id;});$('export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`oche-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
setupMobile();save();render();

function switchEntry(mode){if(data.session.game.dart>0&&data.session.game.status==='playing'){feedback='Finish this round before changing entry mode.';render();return;}entryMode=mode;data.entryMode=mode;typed='';feedback='';save();render();}
function enterTotal(options={}){const s=data.session,g=s.game;if(g.status!=='playing')return;if(!options.bust&&typed==='')return;const total=options.bust?0:Number(typed);
 if(!options.bust&&!options.checkout&&total===g.remaining){if(!D.route(total,3)){feedback='This cannot finish on a double in three darts. Record a bust.';render();return;}document.querySelectorAll('[data-checkout-darts]').forEach(b=>b.disabled=!D.route(total,Number(b.dataset.checkoutDarts)));$('checkoutDialog').showModal();return;}
 try{const next=D.visitTotal(g,total,{...options,hinted:!!data.hints});undoStack.push(structuredClone(s));s.game=next;if(data.hints)s.assisted=true;typed='';feedback=options.bust?'Bust recorded. Score unchanged.':next.status==='won'?'Double out.':next.status==='lost'?'Eight rounds complete.':`${total} scored · ${next.remaining} remaining`;$('checkoutDialog').close();save();render();}catch(e){feedback=e.message;render();}}
function setupMobile(){
 $('settingsButton').onclick=()=>$('settingsDialog').showModal();$('closeSettings').onclick=()=>$('settingsDialog').close();$('totalMode').onclick=()=>switchEntry('total');$('dartMode').onclick=()=>switchEntry('dart');
 $('quickScores').innerHTML=[26,60,85,100,140].map(n=>`<button data-quick="${n}">${n}</button>`).join('');document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{typed=b.dataset.quick;feedback='';render();});
 $('keypad').innerHTML=['1','2','3','4','5','6','7','8','9','C','0','⌫'].map(n=>`<button data-key="${n}" class="${n==='C'||n==='⌫'?'utility':''}" ${n==='⌫'?'aria-label="Delete last digit"':n==='C'?'aria-label="Clear score"':''}>${n}</button>`).join('');document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const key=b.dataset.key;if(key==='C')typed='';else if(key==='⌫')typed=typed.slice(0,-1);else if(typed.length<3)typed=(typed==='0'?'':typed)+key;feedback='';render();});
 $('clearInput').onclick=()=>{typed='';render();};$('submitScore').onclick=()=>enterTotal();$('bustButton').onclick=()=>enterTotal({bust:true});$('cancelCheckout').onclick=()=>$('checkoutDialog').close();$('checkoutBust').onclick=()=>enterTotal({bust:true});document.querySelectorAll('[data-checkout-darts]').forEach(b=>b.onclick=()=>enterTotal({checkout:true,darts:Number(b.dataset.checkoutDarts)}));
}
